create extension if not exists pgcrypto;
create table if not exists google_ads_campaign_daily(user_id uuid not null,customer_id text not null,campaign_id text not null,report_date date not null,campaign_name text,campaign_status text,currency_code text,budget_micros bigint,impressions bigint default 0,clicks bigint default 0,cost_micros bigint default 0,conversions numeric default 0,conversion_value numeric default 0,ctr numeric default 0,average_cpc_micros bigint default 0,synced_at timestamptz default now(),primary key(user_id,customer_id,campaign_id,report_date));
create table if not exists google_ads_change_events(resource_name text primary key,user_id uuid not null,customer_id text not null,campaign_id text,change_date_time timestamptz not null,change_resource_name text,change_resource_type text,operation text,client_type text,user_email text,changed_fields jsonb,old_resource jsonb,new_resource jsonb,summary text,imported_at timestamptz default now());
create table if not exists campaign_notes(id uuid primary key default gen_random_uuid(),user_id uuid not null,customer_id text not null,campaign_id text not null,note_date date not null default current_date,category text default 'observation',title text,content text not null,created_at timestamptz default now(),updated_at timestamptz default now());
create index if not exists metrics_lookup on google_ads_campaign_daily(user_id,report_date,campaign_id);create index if not exists events_lookup on google_ads_change_events(user_id,campaign_id,change_date_time desc);create index if not exists notes_lookup on campaign_notes(user_id,campaign_id,note_date desc);
alter table google_ads_campaign_daily enable row level security;alter table google_ads_change_events enable row level security;alter table campaign_notes enable row level security;
create policy "metrics_owner_read" on google_ads_campaign_daily for select using(auth.uid()=user_id);create policy "events_owner_read" on google_ads_change_events for select using(auth.uid()=user_id);create policy "notes_owner_all" on campaign_notes for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
